from itertools import permutations

def is_valid(board, row, col, num):
    # Check the row
    for x in range(11):
        if board[row][x] == num:
            return False

    # Check the column
    for x in range(11):
        if board[x][col] == num:
            return False

    return True


def solve_sudoku(board):
    for i in range(11):
        for j in range(11):
            if board[i][j] == -1:
                for num in range(11):
                    if is_valid(board, i, j, num):
                        board[i][j] = num
                        if solve_sudoku(board):
                            return True
                        board[i][j] = -1
                return False
    return True

